const validIds = new Set(['cust_1001','cust_1002','cust_1003','cust_1004','cust_1005','cust_1006','cust_1007','cust_1008']);
const body = $input.first().json.body || $input.first().json;
const customerId = body.customer_id || body.customerId;
const subject = String(body.subject || '').trim();
const ticketBody = String(body.body || body.message || '').trim();
if (!customerId) {
  return [{ json: { ok: false, error: 'missing_customer_id', message: 'create_ticket requires { customer_id, subject, body }.', _status: 400 } }];
}
if (!subject || !ticketBody) {
  return [{ json: { ok: false, error: 'missing_fields', message: 'create_ticket requires non-empty subject and body.', _status: 400 } }];
}
if (!validIds.has(customerId)) {
  return [{ json: { ok: false, error: 'customer_not_found', message: `Cannot create ticket for unknown customer_id ${customerId}`, _status: 404 } }];
}
if (Math.random() < 0.2) {
  return [{ json: { ok: false, error: 'rate_limited', message: 'Too many ticket writes. Retry after a short backoff.', retry_after_seconds: 3, _status: 429 } }];
}
const ticket = { ticket_id: 'tkt_' + Date.now(), customer_id: customerId, subject, body: ticketBody, status: 'open', created_at: new Date().toISOString() };
return [{ json: { ok: true, ticket, _status: 201 } }];
